function HookRunner() {
	this._current = null;
	this._entry = null;
}

HookRunner.prototype.invokeCleanup = function(hook) {
	this._entry = hook;

	// A hook cleanup can introduce a call to render which creates a new root, this will call options.vnode
	// and move the currentComponent away.
	const component = this._current;
	const prevComponent = currentComponent;
	let cleanup = this._entry._cleanup;

	if (component != null) {
		const hooks = component.__hooks;
		const callbacks = component._renderCallbacks;
		const vnode = component._vnode;
		const parentDom = component._parentDom;

		if (hooks != null) {
			cleanup = this._entry._cleanup;
		} else if (
			(callbacks != null && callbacks.indexOf(this._entry) != -1) ||
			vnode != null ||
			parentDom != null
		) {
			cleanup = this._entry._cleanup;
		}
	}

	try {
		if (typeof cleanup == 'function') cleanup();
	} finally {
		currentComponent = prevComponent;
	}
};

const hookRunner = new HookRunner();

options._diff = vnode => {
	currentComponent = null;
	if (oldBeforeDiff) oldBeforeDiff(vnode);
};

options._render = vnode => {
	if (oldBeforeRender) oldBeforeRender(vnode);

	currentComponent = vnode._component;
	currentIndex = 0;

	const hooks = currentComponent.__hooks;
	if (hooks) {
		hookRunner._current = currentComponent;
		hooks._pendingEffects.forEach(hookRunner.invokeCleanup, hookRunner);
		hooks._pendingEffects.forEach(invokeEffect);
		hooks._pendingEffects = [];
